        public IList Read(Stream input)
        {
            using var buffer = new MemoryStream();
            input.CopyTo(buffer);
            IConfigRowReader indexed = Open(buffer.ToArray());
            var rows = new List<AllTypesConfig>(indexed.Count);
            for (int i = 0; i < indexed.Count; i++)
            {
                rows.Add((AllTypesConfig)indexed.Read(i));
            }

            return rows;
        }

